const seniorTopics={"daily": ["id-adrc", "id-cil-dac-moscow", "id-cil-dac-post-falls", "id-cil-dac-lewiston", "id-cil-linc-boise", "id-cil-linc-caldwell", "id-cil-linc-twin-falls", "id-cil-life-pocatello", "id-cil-life-blackfoot", "id-cil-life-burley", "id-cil-life-idaho-falls"], "accessibility": ["id-adrc", "id-cil-dac-moscow", "id-cil-dac-post-falls", "id-cil-dac-lewiston", "id-cil-linc-boise", "id-cil-linc-caldwell", "id-cil-linc-twin-falls", "id-cil-life-pocatello", "id-cil-life-blackfoot", "id-cil-life-burley", "id-cil-life-idaho-falls"], "vision": ["id-adrc"], "hearing": ["id-adrc"], "memory": ["alz-dementia-support", "id-adrc"], "costs": ["id-ship", "id-adrc", "id-legal-programs"], "rights": ["id-ombudsman", "id-legal-programs"]};
const ohioLiving=DATA.filter(x=>x.resource_role==='independent_living').map(x=>x.program_id),ohioCaregivers=DATA.filter(x=>x.resource_role==='caregiver_support').map(x=>x.program_id);
const ohioCenters=DATA.filter(x=>x.resource_role==='senior_center').map(x=>x.program_id);
